css:
div:has(> [data-chat-column]) { background-color: var(--sidebar) !important; background-image: var(--surface-grain) !important; background-size: var(--surface-grain-size); background-attachment: fixed; padding: 0 8px 8px 0; }
[data-slot='sidebar-inner'] { background-attachment: fixed; }
body:has([data-slot='sidebar'][data-state='collapsed']) div:has(> [data-chat-column]) { padding-left: 8px; }
[data-slot='sidebar-container'] { border: 0 !important; }
[data-chat-header] { background: transparent !important; }
[data-workspace-area='conversation'] { border: 1px solid var(--border); border-radius: 10px; overflow: hidden; }
[data-thread-terminal-drawer][data-terminal-owner='drawer'] { margin-top: 8px; border: 1px solid var(--border) !important; border-radius: 10px; }
[data-preview-panel-mode='inline'] { background: transparent !important; border-left: 0 !important; }
[data-right-panel-tabbar] { background: transparent !important; }
[data-preview-panel-mode='inline'] [data-right-panel-surface-content] { background: var(--background); border: 1px solid var(--border); border-radius: 10px; overflow: hidden; }
div:has(> [data-chat-column]):has([data-preview-panel-mode='inline'][data-preview-panel-maximized='false']:not([data-workspace-unavailable='true'])) [data-workspace-area='conversation'] { border-right: 0; border-top-right-radius: 0; border-bottom-right-radius: 0; }
[data-preview-panel-mode='inline'][data-preview-panel-maximized='false'] [data-right-panel-surface-content] { border-top-left-radius: 0; border-bottom-left-radius: 0; }
.chat-markdown { color: color-mix(in srgb, var(--foreground) 92%, var(--background)) !important; --info-foreground: var(--app-theme-update-foreground); }
.chat-markdown.leading-relaxed { font-size: 0.9375rem; line-height: 1.7; }
.chat-markdown :is(p, ul, ol, blockquote, pre) { margin-block: 1.2em; }
.chat-markdown :is(strong, b, h1, h2, h3, h4, h5) { color: var(--foreground); }
.chat-markdown :is(h1, h2, h3, h4) { line-height: 1.25; letter-spacing: -0.012em; margin: 1.7em 0 0.6em; }
.chat-markdown h1 { font-size: 1.6em; }
.chat-markdown h2 { font-size: 1.35em; }
.chat-markdown h3 { font-size: 1.15em; }
.chat-markdown h4 { font-size: 1em; }
:root { --context-chip-mention: var(--app-theme-update-foreground) !important; --context-chip-file: var(--app-theme-update-foreground) !important; }
:where(:not(iframe))::-webkit-scrollbar-thumb { background: transparent !important; }
:where(:not(iframe)):hover::-webkit-scrollbar-thumb { background: var(--app-scrollbar-thumb) !important; }
:where(:not(iframe))::-webkit-scrollbar-thumb:hover { background: var(--app-scrollbar-thumb-hover) !important; }
.chat-markdown pre:not(:hover) { scrollbar-color: transparent transparent; }
